'use strict';
const state={boot:null,products:[],contacts:[],references:[],formulas:[],batches:[],projects:[],cart:[],location:1,view:'grid',filters:{},busy:false};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${state.boot?.settings.currency||'AED'} ${((n||0)/100).toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const decimal=(n,p=2)=>(Number(n||0)/10**p).toFixed(p);
const quantity=n=>(Number(n||0)/1000).toLocaleString('en',{maximumFractionDigits:3});
const oldDate=s=>s?new Date(s.replace(' ','T')+(s.includes('Z')?'':'Z')).toLocaleDateString('en',{day:'2-digit',month:'short',year:'numeric'}):'—';
const date=s=>s?new Date(String(s).replace(' ','T')+(/(Z|[+-]\d{2}:\d{2})$/.test(s)||/^\d{4}-\d{2}-\d{2}$/.test(s)?'':'Z')).toLocaleDateString('en',{day:'2-digit',month:'short',year:'numeric'}):'—';
const can=(...roles)=>state.boot?.user.role==='owner'||roles.includes(state.boot?.user.role);
const badge=(s)=>`<span class="badge ${['Posted','Completed','Approved','Accepted','Released','Delivered'].includes(s)?'green':['QC Hold','Declined','Returned','Revision'].includes(s)?'red':['Draft','Review','Planned','Maturing'].includes(s)?'amber':'blue'}">${esc(s)}</span>`;
const options=(rows,label='name',selected='',blank='Choose…')=>`<option value="">${esc(blank)}</option>`+rows.map(r=>`<option value="${r.id}" ${String(r.id)===String(selected)?'selected':''}>${esc(r[label])}</option>`).join('');
const selectOptions=(values,selected='')=>values.map(s=>`<option value="${esc(s)}" ${s===selected?'selected':''}>${esc(s)}</option>`).join('');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
async function api(path,method='GET',data=null,key=null){const headers={Accept:'application/json','X-CSRF-TOKEN':$('meta[name="csrf-token"]').content};let body;if(data instanceof FormData)body=data;else if(data){headers['Content-Type']='application/json';body=JSON.stringify(data);}if(method!=='GET')headers['Idempotency-Key']=key||crypto.randomUUID();let response;try{response=await fetch('/api/'+path,{method,headers,body});}catch{throw new Error('Cannot reach your server. Check the server and network before retrying.');}if(response.status===419)throw new Error('Your session expired. Reload this page and sign in again.');if(response.status===401){location.href='/login';throw new Error('Please sign in again.');}const result=await response.json().catch(()=>({message:'The server could not complete this action.'}));if(!response.ok)throw new Error(result.errors?Object.values(result.errors).flat().join(' '):result.message||'Action failed.');return result;}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><p class="eyebrow">YOUR BUSINESS, CONNECTED</p><h1>${esc(title)}</h1><p class="muted">${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2>${action}</div>${body}</section>`;}
function table(heads,rows,empty='No records yet.'){return rows.length?`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="empty"><h3>A fresh start.</h3>${esc(empty)}</div>`;}
function modal(title,html,wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><h2>${esc(title)}</h2><button class="modal-close" aria-label="Close dialog" onclick="closeModal()">×</button></header><div class="modal-body"><div id="form-error" class="error" hidden></div>${html}</div></section></div>`;setTimeout(()=>$('.modal input,.modal select,.modal button')?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';}
function formActions(text='Save'){return `<div class="form-actions"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button type="submit" class="primary">${text} →</button></div>`;}
function bindForm(handler){const form=$('.modal form');const key=crypto.randomUUID();form.addEventListener('submit',async e=>{e.preventDefault();if(state.busy)return;state.busy=true;const btn=form.querySelector('button[type="submit"]');if(btn)btn.disabled=true;$('#form-error').hidden=true;try{await handler(new FormData(form),key);}catch(err){if($('#form-error')){$('#form-error').textContent=err.message;$('#form-error').hidden=false;$('#form-error').scrollIntoView({block:'nearest'});}else toast(err.message);}finally{state.busy=false;if(btn)btn.disabled=false;}});}
function field(label,name,value='',type='text',extra=''){return `<label ${extra}>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['price','cost','tax','reorder','quantity','amount','charge','credit'].includes(name)?'inputmode="decimal"':''}></label>`;}
async function loadLists(){state.products=(await api('products?location_id='+state.location)).products;if(can('manager','warehouse','accountant','cashier','designer'))state.contacts=(await api('contacts')).contacts;if(can('manager','designer'))state.staff=(await api('staff')).staff;if(can('manager','warehouse','cashier','production'))state.references=(await api('references')).references;}
const navItems=[['customers','◎','Customer 360',['manager']],['dashboard','◫','Overview',['manager','accountant','warehouse','production','cashier','designer']],['catalogue','◇','Perfume catalogue',['manager','accountant','warehouse','production','cashier','designer']],['inventory','▤','Inventory',['manager','warehouse','production','accountant']],['wholesale','↗','Wholesale & invoices',['manager','accountant','warehouse']],['purchasing','↓','Purchasing',['manager','accountant','warehouse']],['pos','▦','Point of sale',['manager','cashier']],['production','⌘','Manufacturing',['manager','production','warehouse']],['formulas','⚗','Secret formulas',['manager','production']],['projects','✧','Design & packaging',['manager','designer']],['reports','▥','Reports',['manager','accountant']],['settings','⚙','Company & access',['manager']]];

const tabletNavigation=window.matchMedia('(max-width: 1180px)');
function setNavigationOpen(open,restoreFocus=false){
 const drawer=tabletNavigation.matches&&open;
 document.body.classList.toggle('nav-open',drawer);
 $('.mobile-menu')?.setAttribute('aria-expanded',String(drawer));
 $('.sidebar').inert=tabletNavigation.matches&&!drawer;
 $('.navigation-backdrop').hidden=!drawer;
 $('.app-main').inert=drawer;
 if(drawer) $('.sidebar .nav-item.active,.sidebar .nav-item')?.focus({preventScroll:true});
 else if(restoreFocus) $('.mobile-menu')?.focus({preventScroll:true});
}
function setupNavigation(){
 const sidebar=$('.sidebar'),button=$('.mobile-menu');
 sidebar.id='app-navigation';
 button.removeAttribute('onclick');
 button.setAttribute('aria-controls',sidebar.id);
 button.setAttribute('aria-expanded','false');
 button.setAttribute('aria-label','Open navigation');
 const backdrop=document.createElement('button');
 backdrop.className='navigation-backdrop';backdrop.type='button';backdrop.hidden=true;
 backdrop.tabIndex=-1;backdrop.setAttribute('aria-label','Close navigation');
 document.body.append(backdrop);
 const close=document.createElement('button');close.className='navigation-close icon-button';
 close.type='button';close.textContent='×';close.setAttribute('aria-label','Close navigation');
 sidebar.prepend(close);
 button.addEventListener('click',()=>setNavigationOpen(!document.body.classList.contains('nav-open')));
 backdrop.addEventListener('click',()=>setNavigationOpen(false,true));
 close.addEventListener('click',()=>setNavigationOpen(false,true));
 $('#navigation').addEventListener('click',e=>{if(e.target.closest('a.nav-item'))setNavigationOpen(false,true);});
 tabletNavigation.addEventListener('change',()=>setNavigationOpen(false));
 document.addEventListener('keydown',e=>{
  if(!document.body.classList.contains('nav-open'))return;
  if(e.key==='Escape'){e.preventDefault();setNavigationOpen(false,true);}
  if(e.key==='Tab'){
   const focus=[...sidebar.querySelectorAll('a[href],button')].filter(x=>!x.disabled&&x.offsetParent!==null);
   const first=focus[0],last=focus.at(-1);
   if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}
   else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}
  }
 });
 setNavigationOpen(false);
}

function navigation(){const page=location.hash.slice(1)||'dashboard';$('#navigation').innerHTML=navItems.filter(x=>can(...x[3])).map((x,i)=>`${x[0]==='reports'?'<div class="nav-separator"></div>':''}<a class="nav-item ${page===x[0]?'active':''}" href="#${x[0]}"><span class="nav-icon">${x[1]}</span>${x[2]}</a>`).join('');}
async function render(){navigation();setNavigationOpen(false);const page=location.hash.slice(1)||'dashboard';const item=navItems.find(x=>x[0]===page);if(!item||!can(...item[3])){$('#content').innerHTML='<div class="empty">You do not have access to this page.</div>';return;}$('#content').innerHTML='<div class="loading"><span class="spinner"></span>Loading…</div>';try{await ({customers:customersPage,dashboard:dashboardPage,catalogue:cataloguePage,inventory:inventoryPage,wholesale:()=>documentsPage(false),purchasing:()=>documentsPage(true),pos:posPage,production:productionPage,formulas:formulaPage,projects:projectsPage,reports:reportsPage,settings:settingsPage}[page])();}catch(e){$('#content').innerHTML=`<div class="error">${esc(e.message)}</div><button class="secondary" onclick="render()">Try again</button>`;}}
async function dashboardPage(){const d=await api('dashboard');const days=Array.from({length:7},(_,i)=>{const dt=new Date();dt.setDate(dt.getDate()-6+i);return {day:dt.toISOString().slice(0,10),label:dt.toLocaleDateString('en',{weekday:'short'})};});const totals=days.map(day=>Number(d.trend.find(t=>t.day===day.day)?.total||0));const max=Math.max(...totals,1);const stat=(label,n,foot,icon)=>`<div class="stat"><span class="stat-icon">${icon}</span><div class="stat-label">${label}</div><div class="stat-number">${n}</div><div class="stat-foot">${foot}</div></div>`;
 $('#content').innerHTML=pageHead('Good to see you, '+state.boot.user.name.split(' ')[0]+'.','Here is what is happening across your perfume business.',`<a class="secondary" href="#catalogue">Browse products ↗</a>${can('manager','cashier')?'<a class="primary" href="#pos">Open POS →</a>':''}`)+`<div class="stats">${stat('Sales · active invoices',d.revenue_cents===null?'Restricted':money(d.revenue_cents),'Posted sales, excluding returned documents','↗')}${stat('Outstanding payments',d.outstanding_cents===null?'Restricted':money(d.outstanding_cents),'Customer balances to collect','◷')}${stat('Products in catalogue',d.products,'Active fragrances, materials & services','◇')}${stat('Batches in progress',d.production,'Mixing, maturation and quality review','⚗')}</div><div class="welcome-banner"><h2>From the first note<br>to the final bottle.</h2><p>Your products, production and customer orders, together in one place.</p></div><div class="dashboard-grid"><div>${panel('Sales over the last 7 days',`<div class="panel-body"><div class="chart">${days.map((day,i)=>`<div class="chart-bar"><b>${d.revenue_cents===null?'—':money(totals[i])}</b><i style="height:${Math.max(2,totals[i]/max*115)}px"></i><span>${day.label}</span></div>`).join('')}</div></div>`)}${panel('Recent documents',table(['Document','Customer','Status','Total'],d.recent.map(r=>`<tr><td><button class="subtle" onclick="documentDetail(${r.id})">${esc(r.number)}</button><small>${esc(r.kind)} · ${date(r.created_at)}</small></td><td>${r.contact_id?'Customer #'+r.contact_id:'Walk-in'}</td><td>${badge(r.status)}</td><td>${money(r.total_cents)}</td></tr>`),'Your first sale or quotation will appear here.'))}</div><div>${panel('Stock to watch',d.low_stock.length?d.low_stock.slice(0,6).map(p=>`<div class="list-row"><span class="badge amber">!</span><span class="grow"><b>${esc(p.name)}</b><small>${esc(p.sku)}</small></span><span>${quantity(p.stock)} <small>${esc(p.unit)}</small></span></div>`).join(''):'<div class="empty">All stocked products are above their reorder level.</div>',`<a class="subtle" href="#inventory">View stock →</a>`)}${panel('Production desk',d.batches.length?d.batches.map(b=>`<div class="list-row"><span class="grow"><b>${esc(b.number)}</b><small>${esc(b.formula_name)} · ${b.planned} planned</small></span>${badge(b.status)}</div>`).join(''):'<div class="empty">No production batches yet.</div>')}${panel('Creative work',`<div class="panel-body"><p class="muted">${d.projects} design or packaging projects in progress.</p><a class="subtle" href="#projects">Open the creative desk →</a></div>`)}</div></div>`;}
function bottle(p){const palettes=[['#d8dace','#8c9d84'],['#e6d6cc','#ac806e'],['#d3ddd9','#62867d'],['#e0d8c1','#ab9564'],['#e0d6db','#a48595']];const [bg,liquid]=palettes[p.id%palettes.length];const name=p.name.split(' ').slice(0,2).join(' ').toUpperCase();if(p.kind==='service')return `<svg viewBox="0 0 150 170" aria-hidden="true"><rect x="25" y="30" width="100" height="125" rx="7" fill="#f9f7ed" stroke="#a5b5a3"/><path d="M45 65h60M45 80h60M45 95h35" stroke="#a5b5a3" stroke-width="3"/><path d="M65 130l12-25 26-26 10 10-26 26z" fill="#718b7b"/><text x="75" y="146" text-anchor="middle" fill="#718b7b" font-size="6">CREATIVE SERVICE</text></svg>`;if(p.kind==='raw')return `<svg viewBox="0 0 150 170" aria-hidden="true"><rect x="47" y="12" width="56" height="22" rx="4" fill="#b9b5a9"/><path d="M48 34h54l12 17v99a9 9 0 0 1-9 9H45a9 9 0 0 1-9-9V51z" fill="${liquid}" opacity=".75"/><rect x="43" y="70" width="65" height="55" fill="#f7f5e9" rx="2"/><text x="75" y="96" text-anchor="middle" fill="#6b6c56" font-size="8">MATERIAL</text><text x="75" y="110" text-anchor="middle" fill="#6b6c56" font-size="6">${esc(p.unit.toUpperCase())}</text></svg>`;if(p.kind==='packaging')return `<svg viewBox="0 0 150 170" aria-hidden="true"><path d="M28 48l46-22 48 22-48 22z" fill="#d8cdb9"/><path d="M28 48v88l46 24V70z" fill="#bba98e"/><path d="M74 70v90l48-24V48z" fill="#cbbda5"/><text x="71" y="112" text-anchor="middle" fill="#8b755b" font-size="7" transform="rotate(27 71 112)">PACKAGING</text></svg>`;return `<svg viewBox="0 0 150 170" aria-hidden="true"><rect x="56" y="7" width="38" height="29" rx="3" fill="#26362f"/><rect x="61" y="34" width="28" height="12" fill="#c5ae83"/><rect x="30" y="44" width="90" height="114" rx="12" fill="${bg}" stroke="${liquid}" stroke-width="1.5"/><rect x="36" y="53" width="78" height="96" rx="8" fill="${liquid}" opacity=".34"/><path d="M40 59v76" stroke="#fff" stroke-width="4" opacity=".3"/><rect x="38" y="81" width="74" height="47" fill="#fff" opacity=".78"/><text x="75" y="97" text-anchor="middle" fill="#596854" font-family="Georgia" font-size="6">ATELIER</text><text x="75" y="111" text-anchor="middle" fill="#52624f" font-size="6">${esc(name)}</text><text x="75" y="121" text-anchor="middle" fill="#87917a" font-size="4">EAU DE PARFUM</text></svg>`;}
function productArt(p,extra=''){const palette=['#eeede6','#f2e8e1','#e9efea','#f0ecdf','#eee8ec'];return `<div class="product-art ${extra}" style="background:${palette[p.id%5]}"><span class="category-badge">${esc(p.concentration||p.kind)}</span>${p.images.length?`<img src="${p.images[0].url}" alt="${esc(p.images[0].alt)}" loading="lazy">`:bottle(p)}</div>`;}
function productCard(p,pos=false){return `<article class="product-card" onclick="${pos?'cartAdd':'productDetail'}(${p.id})">${productArt(p)}<div class="product-info"><h3>${esc(p.name)}</h3><div class="product-subtitle">${esc(p.size||p.sku)} · ${esc(p.audience||p.unit)}</div><div class="scent-tags">${p.families.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="product-bottom"><strong>${p.sales_allowed?money(p.price_cents)+' / '+esc(p.unit):'Internal material'}</strong><span class="${p.stock_milli>0?'muted':''}">${p.kind==='service'?'Service':quantity(p.stock_milli)+' in stock'}</span></div>${pos?`<button class="subtle" onclick="event.stopPropagation();productDetail(${p.id})">Fragrance profile</button>`:''}</div></article>`;}
function catalogueToolbar(pos=false){const f=state.filters;return `<div class="toolbar"><div class="search-box"><input id="catalogue-search" placeholder="Search name, inspiration, SKU or note…" value="${esc(f.search||'')}" aria-label="Search perfumes"></div><select id="filter-family" aria-label="Scent family"><option value="">All scent families</option>${selectOptions([...new Set(['Fresh','Citrus','Floral','Woody','Amber','Fruity','Aquatic','Gourmand','Aromatic','Leather',...state.products.flatMap(p=>p.families)])].sort(),f.family)}</select><select id="filter-audience" aria-label="Audience"><option value="">All audiences</option>${selectOptions(['Men','Women','Unisex'],f.audience)}</select><select id="filter-style" aria-label="Style"><option value="">All styles</option>${selectOptions(['French style','Arabian style','Fusion'],f.style)}</select>${!pos?`<select id="filter-kind" aria-label="Product type"><option value="">All types</option>${selectOptions(['finished','raw','packaging','resale','service','intermediate'],f.kind)}</select><select id="filter-sort" aria-label="Sort products"><option value="name">Name A–Z</option><option value="price-low">Price low to high</option><option value="price-high">Price high to low</option><option value="stock">Stock quantity</option></select><div class="toggle-buttons"><button aria-label="Grid view" class="${state.view==='grid'?'selected':''}" onclick="state.view='grid';catalogueRender()">▦</button><button aria-label="Table view" class="${state.view==='table'?'selected':''}" onclick="state.view='table';catalogueRender()">☷</button></div>`:''}</div>`;}
function filteredProducts(pos=false){const f=state.filters;return state.products.filter(p=>p.active&&(!pos||p.sales_allowed)).filter(p=>!f.search||[p.name,p.sku,p.barcode,p.reference_name,p.reference_brand,...p.notes,...['top_notes','heart_notes','base_notes'].flatMap(k=>profileFor(p)[k]||[]),profileFor(p).smell_description||''].join(' ').toLowerCase().includes(f.search.toLowerCase())).filter(p=>!f.family||p.families.includes(f.family)).filter(p=>!f.audience||p.audience===f.audience).filter(p=>!f.style||p.style===f.style).filter(p=>pos||!f.kind||p.kind===f.kind).filter(p=>!f.available||p.stock_milli>0||p.kind==='service').sort((a,b)=>f.sort==='price-low'?a.price_cents-b.price_cents:f.sort==='price-high'?b.price_cents-a.price_cents:f.sort==='stock'?b.stock_milli-a.stock_milli:a.name.localeCompare(b.name));}
function bindFilters(pos=false){['search','family','audience','style','kind','sort'].forEach(k=>{const el=$('#'+(k==='search'?'catalogue-search':'filter-'+k));if(!el)return;if(k==='search'&&pos)el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const matches=filteredProducts(true);if(matches.length===1){cartAdd(matches[0].id);el.value='';state.filters.search='';}else toast('Choose one matching product.');}});el.addEventListener(k==='search'?'input':'change',()=>{state.filters[k]=el.value;const list=filteredProducts(pos);$('#product-results').innerHTML=pos||state.view==='grid'?`<div class="catalogue">${list.map(p=>productCard(p,pos)).join('')||'<div class="empty">No matching products.</div>'}</div>`:catalogueTable(list);});});}
function catalogueTable(rows){return table(['Product','Classification','Inspiration · internal','Stock','Selling price',''],rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.kind)}</small></td><td>${p.families.map(esc).join(', ')}<small>${esc(p.style)} · ${esc(p.origin)}</small></td><td>${esc([p.reference_brand,p.reference_name].filter(Boolean).join(' · '))||'—'}</td><td>${quantity(p.stock_milli)} ${esc(p.unit)}</td><td>${money(p.price_cents)}</td><td><button class="subtle" onclick="productDetail(${p.id})">Open →</button></td></tr>`));}
async function cataloguePage(){await loadLists();catalogueRender();}
function catalogueRender(){$('#content').innerHTML=pageHead('The perfume catalogue','Find the right fragrance by scent, style or inspiration.',can('manager','warehouse')?'<button class="secondary" onclick="referenceDialog()">+ Inspiration reference</button><button class="primary" onclick="productDialog()">+ Add product</button>':'')+catalogueToolbar()+`<p class="tiny muted">${filteredProducts().length} active products · Inspiration references are internal staff information.</p><div id="product-results">${state.view==='grid'?`<div class="catalogue">${filteredProducts().map(p=>productCard(p)).join('')}</div>`:catalogueTable(filteredProducts())}</div>`;bindFilters();}
function referenceLabel(r){return r.brand+' · '+r.name+(r.gender?' ('+r.gender+')':'');}
function filterReferenceOptions(input){const q=input.value.trim().toLowerCase(),select=input.nextElementSibling;let first=null;for(const o of select.options){if(!o.value){continue;}const r=state.references.find(x=>String(x.id)===o.value)||{};const hit=!q||[r.brand,r.name,r.family,r.notes,r.gender].join(' ').toLowerCase().includes(q);o.hidden=!hit;if(hit&&!first){first=o;}}const current=select.selectedOptions[0];if(q&&first&&(!current||!current.value||current.hidden)){first.selected=true;}}
function referenceDialog(){modal('Add an inspiration reference',`<form><div class="notice">An internal reference fragrance, separate from your own product and its origin. ${state.references.length} references are already in the library.</div><div class="form-grid">${field('Reference brand','brand')}${field('Reference perfume','name')}<label>For<select name="gender"><option value="">Unspecified</option>${selectOptions(['Men','Women','Unisex'],'')}</select></label>${field('Olfactive family','family')}<label class="span2">Key notes / internal notes<textarea name="notes"></textarea></label></div>${formActions('Add reference')}</form>`);bindForm(async fd=>{await api('references','POST',Object.fromEntries(fd));closeModal();toast('Reference added');await cataloguePage();});}
function productDialog(id=null){const p=state.products.find(p=>p.id===id)||{kind:'finished',unit:'bottle',price_cents:0,cost_cents:0,tax_bp:0,reorder_milli:5000,families:[],notes:[],tags:[],active:true};modal(id?'Edit product':'Create a product',`<form><div class="form-grid">${field('Product name','name',p.name)}${field('SKU / internal code','sku',p.sku)}<label>Product type<select name="kind">${selectOptions(['finished','raw','packaging','resale','service','intermediate'],p.kind)}</select></label><label>Base stock unit<select name="unit">${selectOptions(['ml','litre','g','kg','piece','bottle','box','carton','hour'],p.unit)}</select></label>${field('Barcode (optional)','barcode',p.barcode)}${field('Size / edition','size',p.size)}<label>Sell individually<select name="sales_allowed"><option value="1" ${(p.sales_allowed??['finished','resale','service'].includes(p.kind))?'selected':''}>Yes · available in POS and wholesale</option><option value="0" ${(p.sales_allowed??['finished','resale','service'].includes(p.kind))?'':'selected'}>No · internal material only</option></select></label>${field('Selling price per base unit','price',decimal(p.price_cents))}${field('Cost per base unit','cost',decimal(p.cost_cents))}${field('Tax % (company configured)','tax',decimal(p.tax_bp))}${field('Reorder quantity','reorder',decimal(p.reorder_milli,3))}${field('Scent families · comma separated','families',p.families.join(', '))}${field('Additional notes · comma separated','notes',p.notes.join(', '))}${fragranceProfileFields(p)}<label>Style<select name="style"><option value="">Unspecified</option>${selectOptions(['French style','Arabian style','Fusion'],p.style)}</select></label>${field('Actual country of manufacture','origin',p.origin)}<label>Audience<select name="audience"><option value="">Unspecified</option>${selectOptions(['Men','Women','Unisex'],p.audience)}</select></label><label>Concentration<select name="concentration"><option value="">Unspecified</option>${selectOptions(['Parfum','EDP','EDT','Cologne','Attar','Perfume Oil'],p.concentration)}</select></label><label class="span2">Inspired by · internal reference<input type="search" class="reference-search" placeholder="Search ${state.references.length} references by brand, perfume or note…" oninput="filterReferenceOptions(this)" autocomplete="off"><select name="reference_id" size="1">${options(state.references.map(r=>({...r,name:referenceLabel(r)})),'name',p.reference_id,'No reference')}</select></label>${field('Custom tags · comma separated','tags',p.tags.join(', '))}<label>Status<select name="active"><option value="1" ${p.active?'selected':''}>Active</option><option value="0" ${!p.active?'selected':''}>Archived</option></select></label><label class="span2">Description<textarea name="description">${esc(p.description)}</textarea></label></div><p class="form-hint">Quantities use the base unit. Changing an operational item's unit/type is restricted. Upload photos after saving.</p>${formActions('Save product')}</form>`,true);bindForm(async fd=>{const v=Object.fromEntries(fd);['families','notes','tags'].forEach(k=>v[k]=v[k].split(',').map(s=>s.trim()).filter(Boolean));v.active=v.active==='1';v.sales_allowed=v.sales_allowed==='1';v.fragrance_profile={};for(const k of ['top_notes','heart_notes','base_notes']){v.fragrance_profile[k]=String(v[k]||'').split(',').map(s=>s.trim()).filter(Boolean);delete v[k];}for(const k of ['smell_description','intensity','longevity','projection','season','occasion']){v.fragrance_profile[k]=v[k]||'';delete v[k];}v.reference_id=v.reference_id?Number(v.reference_id):null;v.barcode=v.barcode||null;const r=await api('products'+(id?'/'+id:''),'POST',v);closeModal();toast('Product saved');await cataloguePage();productDetail(r.id);});}
function productDetail(id){const p=state.products.find(p=>p.id===id);const similar=state.products.filter(x=>x.id!==id&&x.kind===p.kind&&x.active&&x.families.some(f=>p.families.includes(f))).slice(0,3);modal(p.name,`<div class="detail-grid"><div>${productArt(p,'detail-art')}<div class="scent-tags" style="margin-top:15px">${p.families.map(f=>`<span>${esc(f)}</span>`).join('')}</div></div><div><p class="eyebrow">${esc(p.sku)}</p><h1>${money(p.price_cents)}</h1>${[['Availability',quantity(p.stock_milli)+' '+p.unit],['Sales availability',p.sales_allowed?'Sell individually · '+money(p.price_cents)+' / '+p.unit:'Internal material only'],['Style / actual origin',[p.style,p.origin].filter(Boolean).join(' / ')||'—'],['Audience / concentration',[p.audience,p.concentration].filter(Boolean).join(' / ')||'—'],['Inspiration · internal',[p.reference_brand,p.reference_name].filter(Boolean).join(' · ')||'—'],['Fragrance notes',p.notes.join(', ')||'—'],['Cost per base unit',p.cost_cents===undefined?'Restricted':money(p.cost_cents)]].map(([k,v])=>`<div class="detail-field"><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}<p class="muted tiny">${esc(p.description)}</p></div></div>${fragranceProfileView(p)}${similar.length?`<div class="section-label">Similar scent families</div><div class="notice">${similar.map(x=>esc(x.name)).join(' · ')}<br><small>Matched by shared families; this is not a measured similarity score.</small></div>`:''}${can('manager','warehouse')?`<div class="actions">${can('manager')?`<button class="secondary" onclick="product360(${id})">Full product history</button>`:''}<button class="secondary" onclick="productDialog(${id})">Edit product</button><button class="primary" onclick="imageDialog(${id})">Manage images →</button></div>`:''}`,true);}
function imageDialog(id){const p=state.products.find(p=>p.id===id);modal('Images · '+p.name,`<p class="muted">Upload product photos. The first image is used in the catalogue and POS.</p><div class="image-gallery">${p.images.map((i,n)=>`<div class="image-tile"><img src="${i.url}" alt="${esc(i.alt)}"><div><button onclick="imageAction(${i.id},'cover',${id})">${n?'Make cover':'✓ Cover'}</button><button onclick="imageAction(${i.id},'delete',${id})">Remove</button></div></div>`).join('')}</div><form><div class="drop-zone">JPG, PNG or WebP · up to 8 MB<br><input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></div>${field('Image description','alt',p.name)}${formActions('Upload image')}</form>`);bindForm(async fd=>{await api(`products/${id}/images`,'POST',fd);await loadLists();imageDialog(id);toast('Image uploaded');});}
async function imageAction(id,action,product){try{await api('images/'+id,'POST',{action});await loadLists();imageDialog(product);toast(action==='cover'?'Cover updated':'Image removed');}catch(e){toast(e.message);}}
async function inventoryPage(){await loadLists();const d=await api('inventory');$('#content').innerHTML=pageHead('Inventory, with a paper trail.','Lot balances and every movement, across your locations.',can('manager','warehouse')?'<button class="primary" onclick="stockDialog()">+ Adjust / transfer stock</button>':'')+`<div class="notice">Opening stock, adjustments and transfers require a reason. Purchase receipts, production and sales update this ledger automatically.</div>`+panel('Stock by location and lot',table(['Product','Location','Lot','Available quantity'],d.balances.map(b=>`<tr><td><strong>${esc(b.name)}</strong><small>${esc(b.sku)}</small></td><td>${esc(b.location)}</td><td>${esc(b.lot)}</td><td>${quantity(b.quantity_milli)} ${esc(b.unit)}</td></tr>`)))+panel('Recent movement history',table(['Date','Product','Location / lot','Change','Reason / source'],d.movements.map(m=>`<tr><td>${date(m.created_at)}</td><td>${esc(m.name)}</td><td>${esc(m.location)}<small>${esc(m.lot)}</small></td><td><span class="badge ${m.quantity_milli>0?'green':'red'}">${m.quantity_milli>0?'+':''}${quantity(m.quantity_milli)} ${esc(m.unit)}</span></td><td>${esc(m.reason)}<small>${esc(m.source)}</small></td></tr>`)),'<a class="subtle" href="/api/export?type=stock">Export CSV ↓</a>');}
function stockDialog(){modal('Adjust or transfer inventory',`<form><div class="form-grid"><label class="span2">Product<select name="product_id" required>${options(state.products.filter(p=>p.active&&p.kind!=='service'))}</select></label><label>Source / working location<select name="location_id">${options(state.boot.locations,'name',state.location)}</select></label><label>Transfer destination (optional)<select name="target_id">${options(state.boot.locations,'name','','Adjustment only')}</select></label>${field('Lot code (must match for deduction)','lot','GENERAL')}${field('Quantity · negative for adjustment deduction','quantity','1')}<label class="span2">Reason<textarea name="reason" placeholder="Opening balance, count correction or transfer reason" required></textarea></label></div><p class="form-hint">Quantities are in the product's base stock unit. Transfers require a positive quantity and move the same lot.</p>${formActions('Post stock movement')}</form>`);bindForm(async(fd,key)=>{const v=Object.fromEntries(fd);v.target_id=v.target_id?Number(v.target_id):null;await api('stock','POST',v,key);closeModal();toast('Stock ledger updated');await inventoryPage();});}
async function documentsPage(purchase){await loadLists();const d=await api('documents'+(purchase?'?kind=Purchase':''));const docs=purchase?d.documents:d.documents.filter(x=>x.kind!=='Purchase');$('#content').innerHTML=pageHead(purchase?'Purchasing':'Wholesale & invoices',purchase?'Record supplier purchases and receive stock into a location.':'Quotations, posted invoices, payments and full returns.',`<button class="secondary" onclick="contactsDialog('${purchase?'supplier':'customer'}')">${purchase?'Suppliers':'Customers'}</button>${purchase?'':`<button class="secondary" onclick="documentDialog('Quotation')">+ Quotation</button>`}<button class="primary" onclick="documentDialog('${purchase?'Purchase':'Invoice'}')">+ ${purchase?'Receive purchase':'Create invoice'}</button>`)+`<div class="notice">${purchase?'A posted purchase receives the listed goods immediately. Partial purchase orders and supplier returns are later-stage features.':'Invoices deduct stock immediately. Quotations do not reserve or deduct stock. Separate sales orders, partial deliveries and partial returns are later-stage features.'}</div>`+panel(purchase?'Purchase receipts':'Sales documents',table(['Number','Customer / supplier','Status','Total','Paid','Balance','Date'],docs.map(d=>`<tr><td><button class="subtle" onclick="documentDetail(${d.id})">${esc(d.number)}</button><small>${esc(d.kind)}</small></td><td>${esc(d.contact||'Walk-in')}</td><td>${badge(d.status)}</td><td>${money(d.total_cents)}</td><td>${money(d.paid_cents)}</td><td>${money(['Returned','Declined','Draft','Accepted'].includes(d.status)?0:d.total_cents-d.paid_cents)}</td><td>${date(d.created_at)}</td></tr>`)),'<a href="/api/export?type=sales" class="subtle">Export CSV ↓</a>');}
function contactsDialog(kind='customer'){const list=state.contacts.filter(c=>c.kind===kind);modal(kind==='supplier'?'Supplier directory':'Customer directory',table(['Name','Contact','Credit limit'],list.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone||c.email||'—')}</td><td>${money(c.credit_cents)}</td></tr>`))+`<div class="form-actions"><button class="primary" onclick="contactCreate('${kind}')">+ Add ${kind}</button></div>`,true);}
function contactCreate(kind){modal('Add '+kind,`<form><div class="form-grid">${field('Name / company','name')}${field('Email','email','','email')}${field('Phone','phone')}${field('Tax identifier','tax_id')}${field('Credit limit','credit','0.00')}${field('Payment terms · days','terms_days','0','number')}<label class="span2">Address<textarea name="address"></textarea></label></div>${formActions('Save contact')}</form>`);bindForm(async fd=>{await api('contacts','POST',{...Object.fromEntries(fd),kind});await loadLists();contactsDialog(kind);toast('Contact created');});}
function documentDialog(kind){const selectable=state.products.filter(p=>p.active&&(kind==='Purchase'?p.kind!=='service':p.sales_allowed));state.docProducts=selectable;modal(kind==='Purchase'?'Receive a purchase':kind==='Quotation'?'Create a quotation':'Create a wholesale invoice',`<form><div class="form-grid"><label>${kind==='Purchase'?'Supplier':'Customer'}<select name="contact_id">${options(state.contacts.filter(c=>c.kind===(kind==='Purchase'?'supplier':'customer')),'name','','Walk-in / no contact')}</select></label><label>Stock location<select name="location_id">${options(state.boot.locations,'name',state.location)}</select></label>${field('Supplier bill / customer reference','bill_reference','')}${field('Payment due date','due_date','','date')}${field('Payment now (quotations: zero)','paid','0.00')}<label>Payment method<select name="method">${selectOptions(['Credit','Cash','Card','Bank'],'Credit')}</select></label></div><div class="section-label">Items · quantity / unit price / line discount</div><div id="doc-lines"></div><button type="button" class="secondary" onclick="addDocumentLine('${kind}')">+ Add item</button><div class="document-total" id="draft-total">Add items to see the estimated total.</div><label style="margin-top:15px">Notes<textarea name="notes"></textarea></label>${formActions(kind==='Quotation'?'Save quotation':'Post document')}</form>`,true);addDocumentLine(kind);bindForm(async(fd,key)=>{const lines=Array.from(document.querySelectorAll('#doc-lines .line-editor')).map(el=>({product_id:Number(el.querySelector('[data-product]').value),quantity:el.querySelector('[data-qty]').value,price:el.querySelector('[data-price]').value,discount:el.querySelector('[data-discount]').value}));const v={...Object.fromEntries(fd),kind,lines};v.contact_id=v.contact_id?Number(v.contact_id):null;const r=await api('documents','POST',v,key);closeModal();toast(r.number+' posted');await render();await documentDetail(r.id);});}
function addDocumentLine(kind){const div=document.createElement('div');div.className='line-editor';div.innerHTML=`<select data-product required>${options(state.docProducts)}</select><input data-qty aria-label="Quantity" value="1" inputmode="decimal"><input data-price aria-label="Unit price" value="0.00" inputmode="decimal"><input data-discount aria-label="Line discount" value="0.00" inputmode="decimal"><button type="button" class="remove" aria-label="Remove line">×</button>`;div.querySelector('[data-product]').onchange=()=>{const p=state.docProducts.find(p=>p.id===Number(div.querySelector('[data-product]').value));div.querySelector('[data-price]').value=decimal(kind==='Purchase'?p?.cost_cents:p?.price_cents);draftTotal();};div.querySelector('.remove').onclick=()=>{div.remove();draftTotal();};div.addEventListener('input',draftTotal);$('#doc-lines').append(div);}
function draftTotal(){let total=0;document.querySelectorAll('#doc-lines .line-editor').forEach(el=>{const p=state.docProducts.find(p=>p.id===Number(el.querySelector('[data-product]').value));const subtotal=Number(el.querySelector('[data-qty]').value)*Number(el.querySelector('[data-price]').value)-Number(el.querySelector('[data-discount]').value);total+=Math.max(0,subtotal)*(1+(p?.tax_bp||0)/10000);});$('#draft-total').innerHTML=`<span class="muted tiny">Estimated total · server validates and rounds each line</span><strong>${money(Math.round(total*100))}</strong>`;}
async function documentDetail(id){try{const d=await api('documents/'+id);const p=d.document;const s=p.seller_snapshot?(typeof p.seller_snapshot==='string'?JSON.parse(p.seller_snapshot):p.seller_snapshot):state.boot.settings;modal(p.number,`<article class="document-preview"><div class="document-header"><div><p class="eyebrow">${esc(s.company_name)}</p><h1>${esc(p.kind==='Sale'?'SALES RECEIPT':p.kind.toUpperCase())}</h1><p class="muted tiny">${esc(s.address||'')}<br>${esc(s.phone||'')} · ${esc(s.email||'')}<br>${s.tax_id?'Tax ID: '+esc(s.tax_id):''}</p></div><div class="right"><h2>${esc(p.number)}</h2>${badge(p.status)}<p class="tiny muted" style="margin-top:10px">${date(p.created_at)}${p.due_date?'<br>Due '+date(p.due_date):''}${p.bill_reference?'<br>Reference: '+esc(p.bill_reference):''}</p></div></div><div class="document-meta"><div><small class="muted">${p.kind==='Purchase'?'Supplier':'Customer'}</small><br><b>${esc(d.contact?.name||'Walk-in customer')}</b><br><small>${esc(d.contact?.address||'')}<br>${esc(d.contact?.phone||'')} ${esc(d.contact?.email||'')}${d.contact?.tax_id?'<br>Tax ID: '+esc(d.contact.tax_id):''}</small></div><div class="right"><small class="muted">Payment method</small><br>${esc(p.method)}</div></div>${table(['Item','Qty / unit','Unit price','Discount','Tax','Total'],d.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${quantity(l.quantity_milli)} ${esc(l.unit)}</td><td>${money(l.price_cents)}</td><td>${money(l.discount_cents)}</td><td>${money(l.tax_cents)}</td><td>${money(l.total_cents)}</td></tr>`))}<div class="document-total"><p>Subtotal ${money(p.subtotal_cents)} · Tax ${money(p.tax_cents)}</p><strong>${money(p.total_cents)}</strong><small>Paid ${money(p.paid_cents)} · ${p.status==='Returned'?'Returned':`Balance ${money(p.total_cents-p.paid_cents)}`}</small></div><p class="tiny muted" style="margin-top:20px">${esc(p.notes||'Thank you for your business.')}</p></article>${invoiceCostView(d)}<div class="form-actions"><button class="secondary" onclick="window.print()">Print / save PDF</button>${can('manager','accountant')&&p.status==='Draft'&&p.kind==='Quotation'?`<button class="secondary" onclick="quotationAction(${id},'decline')">Decline</button><button class="primary" onclick="quotationAction(${id},'accept')">Accept quotation</button>`:''}${can('manager','accountant')&&p.status==='Posted'&&p.kind!=='Return'?`${p.paid_cents<p.total_cents?`<button class="primary" onclick="paymentDialog(${id},${p.total_cents-p.paid_cents})">Record payment</button>`:''}${['Sale','Invoice'].includes(p.kind)?`<button class="danger" onclick="returnDialog(${id})">Full return</button>`:''}`:''}</div>`,true);}catch(e){toast(e.message);}}
async function quotationAction(id,action){try{await api('documents/'+id,'POST',{action});toast('Quotation '+(action==='accept'?'accepted':'declined'));await render();await documentDetail(id);}catch(e){toast(e.message);}}
function paymentDialog(id,balance){modal('Record payment',`<form><p>Outstanding: <b>${money(balance)}</b></p>${field('Payment amount','amount',decimal(balance))}<label style="margin-top:15px">Method<select name="method">${selectOptions(['Cash','Card','Bank'])}</select></label>${formActions('Record payment')}</form>`);bindForm(async(fd,key)=>{await api('documents/'+id,'POST',{action:'payment',...Object.fromEntries(fd)},key);closeModal();toast('Payment recorded');await render();await documentDetail(id);});}
function returnDialog(id){modal('Full return and refund record',`<form><div class="notice">This reverses the complete sale once. Record the real refund outside this application if it was paid by card/bank; there is no payment-provider connection.</div><label>Returned stock condition<select name="condition">${selectOptions(['Restock','Do not restock'])}</select></label>${formActions('Confirm full return')}</form>`);bindForm(async(fd,key)=>{const r=await api('documents/'+id,'POST',{action:'return',...Object.fromEntries(fd)},key);closeModal();toast('Return recorded · refund '+money(r.refund_cents));await render();await documentDetail(r.id);});}
async function posPage(){await loadLists();const d=await api('shifts');state.openShift=d.shifts.find(s=>!s.closed_at);$('#content').innerHTML=pageHead('Point of sale','Find a fragrance. Build the basket. Make their day.',`<button class="secondary" onclick="shiftDialog()">${state.openShift?'Close shift':'Open shift'} · ${state.openShift?'active':'required'}</button>`)+(!state.openShift?'<div class="notice">Open your cashier shift before posting a sale.</div>':'')+`<div class="pos-layout"><section>${catalogueToolbar(true)}<div id="product-results"><div class="catalogue">${filteredProducts(true).map(p=>productCard(p,true)).join('')}</div></div></section><section class="panel cart-panel"><div class="panel-head"><h2>Current basket</h2><button class="subtle" onclick="state.cart=[];cartRender()">Clear</button></div><div class="panel-body" id="cart"></div></section></div>`;bindFilters(true);cartRender();}
function cartAdd(id){const p=state.products.find(p=>p.id===id);if(p.kind!=='service'&&p.stock_milli<=0){toast('This product has no available stock.');return;}const prior=state.cart.find(l=>l.id===id);if(prior)prior.qty++;else state.cart.push({id,qty:1});cartRender();}
function cartChange(id,n){const line=state.cart.find(l=>l.id===id);line.qty+=n;if(line.qty<1)state.cart=state.cart.filter(l=>l.id!==id);cartRender();}
function cartRender(){const el=$('#cart');if(!el)return;const lines=state.cart.map(l=>({...l,p:state.products.find(p=>p.id===l.id)}));let subtotal=0,tax=0;lines.forEach(l=>{const net=Math.round(l.qty*l.p.price_cents);subtotal+=net;tax+=Math.round(net*l.p.tax_bp/10000);});state.cartTotal=subtotal+tax;el.innerHTML=lines.length?lines.map(l=>`<div class="cart-line"><div><b>${esc(l.p.name)}</b><br><small>${money(l.p.price_cents)} / ${esc(l.p.unit)}</small><div class="cart-quantity"><button onclick="cartChange(${l.id},-1)" aria-label="Decrease quantity">−</button><input aria-label="Quantity in ${esc(l.p.unit)}" inputmode="decimal" value="${l.qty}" onchange="cartSet(${l.id},this.value)"><small>${esc(l.p.unit)}</small><button onclick="cartChange(${l.id},1)" aria-label="Increase quantity">+</button></div></div><strong>${money(Math.round(l.qty*l.p.price_cents))}</strong></div>`).join('')+`<div class="cart-summary"><div><span>Subtotal</span><b>${money(subtotal)}</b></div><div><span>Tax</span><b>${money(tax)}</b></div><div class="total"><span>Total</span><b>${money(state.cartTotal)}</b></div></div><button class="primary full" onclick="checkoutDialog()">Take payment →</button>`:'<div class="empty">Your basket is empty.<br>Select a product to begin.</div>';}
function checkoutDialog(){if(!state.openShift){shiftDialog();return;}modal('Complete sale',`<form><div class="document-total"><span>Total to pay</span><strong>${money(state.cartTotal)}</strong></div><div class="form-grid" style="margin-top:20px"><label class="span2">Customer<select name="contact_id">${options(state.contacts.filter(c=>c.kind==='customer'),'name','','Walk-in customer')}</select></label>${field('Amount received','paid',decimal(state.cartTotal))}<label>Payment method<select name="method">${selectOptions(['Cash','Card','Bank','Credit'])}</select></label></div><p class="form-hint">Enter the exact applied payment. Tender/change and split payments are not yet supported. Card records do not charge a terminal.</p>${formActions('Post sale')}</form>`);bindForm(async(fd,key)=>{const v=Object.fromEntries(fd);v.contact_id=v.contact_id?Number(v.contact_id):null;v.kind='Sale';v.location_id=state.location;v.lines=state.cart.map(l=>({product_id:l.id,quantity:String(l.qty)}));const r=await api('documents','POST',v,key);state.cart=[];closeModal();toast(r.number+' completed');await posPage();await documentDetail(r.id);});}
function shiftDialog(){const s=state.openShift;modal(s?'Close cashier shift':'Open cashier shift',`<form>${s?`<p>Expected cash: <b>${money(s.expected_cents)}</b></p><p class="muted tiny">Opening float plus cash receipts less recorded cash refunds.</p>`:''}${field(s?'Counted cash':'Opening cash float','amount','0.00')}${formActions(s?'Close shift':'Open shift')}</form>`);bindForm(async(fd,key)=>{const r=await api('shifts','POST',{action:s?'close':'open',amount:fd.get('amount')},key);closeModal();toast(s?'Shift closed · variance '+money(r.variance_cents):'Shift opened');await posPage();});}
async function formulaPage(){await loadLists();state.formulas=(await api('formulas')).formulas;$('#content').innerHTML=pageHead('Formulas, kept confidential.','Versioned recipes and packaging quantities per finished bottle.',`<button class="primary" onclick="formulaDialog()">+ Formula version</button>`)+`<div class="notice">This build uses material quantities in each item's base unit per bottle. It does not convert density or mass/volume automatically. Released versions are preserved.</div>`+panel('Formula library',table(['Code / version','Formula','Output product','Materials','Status',''],state.formulas.map(f=>`<tr><td>${esc(f.code)}<small>Version ${f.version}</small></td><td>${esc(f.name)}</td><td>${esc(f.product)}</td><td>${f.ingredients.length} ingredients · ${f.packaging.length} packaging</td><td>${badge(f.status)}</td><td><button class="subtle" onclick="formulaDetail(${f.id})">Open →</button></td></tr>`)));}
function formulaDialog(from=null){const f=state.formulas.find(f=>f.id===from);state.formulaMaterials=state.products.filter(p=>p.active&&['raw','intermediate','packaging'].includes(p.kind));modal('New formula version',`<form><div class="form-grid">${field('Formula code','code',f?.code||'')}${field('Formula name','name',f?.name||'')}<label>Finished output product<select name="product_id" required>${options(state.products.filter(p=>p.kind==='finished'&&['bottle','piece'].includes(p.unit)),'name',f?.product_id)}</select></label>${field('Maturation period · days','maturation_days',f?.maturation_days||'0','number')}</div><div class="section-label">Ingredients per finished bottle</div><div id="ingredient-lines"></div><button type="button" class="secondary" onclick="formulaLine('ingredient')">+ Ingredient</button><div class="section-label">Packaging per finished bottle</div><div id="packaging-lines"></div><button type="button" class="secondary" onclick="formulaLine('packaging')">+ Packaging item</button><label style="margin-top:18px">Mixing / production instructions<textarea name="instructions">${esc(f?.instructions)}</textarea></label>${formActions('Save draft version')}</form>`,true);(f?.ingredients||[null]).forEach(x=>formulaLine('ingredient',x));(f?.packaging||[]).forEach(x=>formulaLine('packaging',x));bindForm(async fd=>{const rows=container=>Array.from(document.querySelectorAll(container+' .line-editor')).map(el=>({product_id:Number(el.querySelector('select').value),quantity:el.querySelector('input').value}));await api('formulas','POST',{...Object.fromEntries(fd),ingredients:rows('#ingredient-lines'),packaging:rows('#packaging-lines')});closeModal();toast('Draft formula saved');await formulaPage();});}
function formulaLine(kind,row=null){const div=document.createElement('div');div.className='line-editor formula';const list=state.formulaMaterials.filter(p=>kind==='packaging'?p.kind==='packaging':['raw','intermediate'].includes(p.kind)).map(p=>({...p,name:p.name+' ['+p.unit+']'}));div.innerHTML=`<select required>${options(list,'name',row?.product_id)}</select><input aria-label="Quantity per bottle in base unit" value="${row?decimal(row.quantity_milli,3):'1'}" inputmode="decimal"><button type="button" class="remove" aria-label="Remove ingredient">×</button>`;div.querySelector('button').onclick=()=>div.remove();$(kind==='packaging'?'#packaging-lines':'#ingredient-lines').append(div);}
function formulaDetail(id){const f=state.formulas.find(f=>f.id===id);modal(f.name+' · v'+f.version,`<p>${badge(f.status)} <span class="muted tiny">${esc(f.code)} · Output ${esc(f.product)} · ${f.maturation_days} maturation days</span></p>${costSheetView(f.costing,'Estimated materials per bottle')}${table(['Material / packaging','Quantity per bottle','Base unit'],[...f.ingredients,...f.packaging].map(i=>`<tr><td>${esc(i.name)}</td><td>${quantity(i.quantity_milli)}</td><td>${esc(i.unit)}</td></tr>`))}<p class="muted" style="margin-top:20px">${esc(f.instructions||'No additional instructions.')}</p><div class="form-actions"><button class="secondary" onclick="formulaDialog(${id})">Create next version</button>${f.status==='Draft'&&can('manager')?`<button class="primary" onclick="approveFormula(${id})">Approve formula</button>`:''}</div>`,true);}
async function approveFormula(id){try{await api('formulas/'+id+'/approve','POST',{});closeModal();toast('Formula approved');await formulaPage();}catch(e){toast(e.message);}}
async function productionPage(){await loadLists();if(can('manager','production'))state.formulas=(await api('formulas')).formulas;state.batches=(await api('batches')).batches;$('#content').innerHTML=pageHead('The production desk','Track output, ingredient and packaging costs, labour and batch profitability.',can('manager','production')?'<button class="primary" onclick="batchDialog()">+ Plan batch</button>':'')+`<div class="notice">Batch materials and packaging are issued from the approved per-bottle BOM. Actual consumption overrides, staged bottling and rework are later-stage features.</div>`+panel('Batches',table(['Batch','Product / formula','Planned','Accepted / rejected','Status','Batch cost / unit',''],state.batches.map(b=>`<tr><td>${esc(b.number)}<small>${date(b.created_at)}</small></td><td>${esc(b.product)}<small>${esc(b.formula_name)} · v${b.version}</small></td><td>${b.planned}</td><td>${b.accepted} / ${b.rejected}</td><td>${badge(b.status)}</td><td>${b.costing?(money((b.costing.actual||b.costing.estimate||b.costing.issued)?.total_cents)):'—'}<small>${b.costing?.actual?'Recorded':b.costing?.estimate?'Estimated':'Legacy'} · ${b.costing?(money((b.costing.actual||b.costing.estimate||b.costing.issued)?.unit_cost_cents)):'—'} / unit</small></td><td><button class="subtle" onclick="batchDetail(${b.id})">Open →</button></td></tr>`)));}
function batchDialog(){modal('Plan a production batch',`<form><div class="form-grid"><label class="span2">Approved formula<select name="formula_id" required>${options(state.formulas.filter(f=>f.status==='Approved').map(f=>({...f,name:f.name+' · v'+f.version})))}</select></label><label>Material and output location<select name="location_id">${options(state.boot.locations,'name',state.location)}</select></label>${field('Planned bottles / pieces','planned','100','number')}${extraCostFields('estimated_')}</div><p class="form-hint">Materials are estimated from the approved formula. Additional costs are for the whole batch.</p>${formActions('Plan batch')}</form>`);bindForm(async(fd,key)=>{await api('batches','POST',Object.fromEntries(fd),key);closeModal();toast('Batch planned');await productionPage();});}
function batchDetail(id){const b=state.batches.find(b=>b.id===id);const controls={Planned:['issue','Issue materials'],Mixing:['mature','Start maturation'],Maturing:['qc','Record quality check'],'QC Hold':['recheck','Recheck quality'],Released:['complete','Complete batch']};const c=controls[b.status];modal(b.number,`<p>${badge(b.status)} <span class="muted tiny">${esc(b.product)} · ${esc(b.formula_name)} v${b.version}</span></p><div class="metric-grid"><div><small>Planned output</small><b>${b.planned}</b></div><div><small>Accepted output</small><b>${b.accepted}</b></div><div><small>Issued material cost</small><b>${money(b.material_cost_cents)}</b></div></div>${batchCostView(b)}<p class="muted tiny" style="margin-top:15px">${b.matures_at?'Maturation due '+date(b.matures_at):'Maturation not started'}<br>${esc(b.qc_notes||'No quality observations yet.')}<br>${esc(b.loss_reason||'')}</p>${c&&can('manager','production')?`<form><input type="hidden" name="action" value="${c[0]}">${c[0]==='qc'?'<label>Quality observations<textarea name="qc_notes" required></textarea></label><label style="margin-top:15px">Decision<select name="passed"><option value="1">Pass / release</option><option value="0">Fail / hold</option></select></label>':''}${c[0]==='complete'?`<div class="form-grid">${field('Accepted bottles','accepted',String(b.planned),'number')}${field('Rejected / lost bottles','rejected','0','number')}${extraCostFields()}<label class="span2">Loss explanation<textarea name="loss_reason"></textarea></label></div>`:''}<div class="notice" style="margin-top:15px">${c[0]==='issue'?'This deducts all required materials and packaging. Insufficient stock blocks the whole action.':c[0]==='complete'?'Only accepted output is added to stock. Accepted plus rejected must equal planned output.':'This advances the batch workflow and records the action.'}</div>${formActions(c[1])}</form>`:''}`,true);if(c&&can('manager','production'))bindForm(async(fd,key)=>{const v=Object.fromEntries(fd);if(v.passed!==undefined)v.passed=v.passed==='1';await api('batches/'+id,'POST',v,key);closeModal();toast('Batch updated');await productionPage();});}
async function projectsPage(){await loadLists();if(can('manager'))state.batches=(await api('batches')).batches;state.projects=(await api('projects')).projects;$('#content').innerHTML=pageHead('The creative desk','Design briefs, packaging, print specifications and versioned artwork.',`<button class="primary" onclick="projectDialog()">+ New project</button>`)+`<div class="notice">Artwork approvals are recorded by authorized managers, with their identity and comments. A customer approval portal and production-order linkage are later-stage features.</div><div class="project-grid">${state.projects.map(p=>`<article class="project-card" onclick="projectDetail(${p.id})"><span class="project-icon">${p.type==='Printing'?'▤':p.type==='Packaging'?'◇':'✧'}</span><p class="eyebrow">${esc(p.type)}</p><h3>${esc(p.name)}</h3><small class="muted">${esc(p.customer||'Internal project')}</small><p class="brief">${esc(p.brief)}</p>${badge(p.status)}<div class="card-footer"><span>${esc(p.designer||'Unassigned')}</span><span>Due ${p.due_date||'not set'}</span></div></article>`).join('')||'<div class="empty">Create your first design or packaging project.</div>'}</div>`;}
function projectDialog(){modal('Create a creative project',`<form><div class="form-grid">${field('Project name','name')}<label>Project type<select name="type">${selectOptions(['Design','Printing','Packaging','Private Label'])}</select></label><label>Customer<select name="contact_id">${options(state.contacts.filter(c=>c.kind==='customer'),'name','','Internal project')}</select></label>${field('Due date','due_date','','date')}<label>Linked product<select name="product_id">${options(state.products,'name','','No product link')}</select></label><label>Linked production batch<select name="batch_id">${options((state.batches||[]).map(b=>({...b,name:b.number+' · '+b.product})),'name','','No batch link')}</select></label><label>Packaging / printing vendor<select name="supplier_id">${options(state.contacts.filter(c=>c.kind==='supplier'),'name','','No vendor')}</select></label><label>Assigned designer<select name="assigned_id">${options(state.staff||[],'name','','Unassigned')}</select></label>${field('Quoted charge','charge','0.00')}${field('Estimated job cost','cost','0.00')}<label class="span2">Brief<textarea name="brief" required placeholder="Customer requirements, deliverables, design direction…"></textarea></label><label class="span2">Print / packaging specification<textarea name="specification" placeholder="Dimensions, material, quantities, finishing, outsourcing…"></textarea></label></div>${formActions('Create project')}</form>`);bindForm(async fd=>{const v=Object.fromEntries(fd);v.contact_id=v.contact_id?Number(v.contact_id):null;v.due_date=v.due_date||null;v.assigned_id=v.assigned_id?Number(v.assigned_id):null;for(const k of ['product_id','batch_id','supplier_id'])v[k]=v[k]?Number(v[k]):null;await api('projects','POST',v);closeModal();toast('Project created');await projectsPage();});}
function projectDetail(id){const p=state.projects.find(p=>p.id===id);modal(p.name,`<p>${badge(p.status)} <span class="muted tiny">${esc(p.type)} · ${esc(p.customer||'Internal project')}</span></p><p>${esc(p.brief)}</p><div class="notice">${esc(p.specification||'No print specifications recorded.')}</div>${p.charge_cents!==undefined?`<div class="metric-grid"><div><small>Quoted charge</small><b>${money(p.charge_cents)}</b></div><div><small>Estimated cost</small><b>${money(p.cost_cents)}</b></div><div><small>Estimated margin</small><b>${money(p.charge_cents-p.cost_cents)}</b></div></div>`:''}<div class="section-label">Artwork versions</div>${table(['Version','File','Uploaded',''],p.artworks.map(a=>`<tr><td>v${a.version} ${p.approved_artwork_id===a.id?'✓ approved':''}</td><td>${esc(a.filename)}<small>${esc(a.comment)}</small></td><td>${date(a.created_at)}</td><td><a class="subtle" href="/api/artwork/${a.id}">Download ↓</a></td></tr>`),'Upload the first proof to begin review.')}<div class="timeline">${p.approvals.map(a=>`<div>${esc(a.decision)} · artwork #${a.artwork_id}<small>${a.source==='customer'?'Customer: '+esc(a.customer_name)+' · '+esc(a.customer_phone)+' · ':''}${esc(a.comment)} · ${date(a.created_at)}</small></div>`).join('')}</div>${p.status!=='Delivered'?`<div class="actions">${can('manager')?`<button class="secondary" onclick="projectLinksDialog(${id})">Link customer / product / vendor</button>`:''}<button class="secondary" onclick="customerArtworkLink(${id})">Customer artwork link / WhatsApp</button><button class="secondary" onclick="artworkDialog(${id})">Upload mockup / revision</button>${can('manager')&&p.artworks.length?`<button class="secondary" onclick="projectApprovalDialog(${id},'revise')">Request revision</button><button class="primary" onclick="projectApprovalDialog(${id},'approve')">Approve latest artwork</button>`:''}${can('manager')&&p.status==='Approved'?`<button class="primary" onclick="projectApprovalDialog(${id},'deliver')">Mark delivered</button>`:''}</div>`:''}`,true);}
function artworkDialog(id){modal('Upload artwork revision',`<form><div class="drop-zone">PDF, JPG, PNG or WebP · up to 16 MB<br><input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required></div><label style="margin-top:15px">Revision comments<textarea name="comment"></textarea></label><p class="form-hint">A new upload clears active approval and requires a new review. Existing approved files remain in history. Native source files are not accepted in this build.</p>${formActions('Upload revision')}</form>`);bindForm(async fd=>{await api('projects/'+id+'/artwork','POST',fd);await projectsPage();projectDetail(id);toast('Artwork revision uploaded');});}
function projectApprovalDialog(id,action){const p=state.projects.find(p=>p.id===id);modal(action==='approve'?'Approve artwork':action==='deliver'?'Confirm delivery':'Request revision',`<form><div class="notice">${action==='approve'?'This records your manager approval of the latest file version. Enter customer authorization evidence if approving on their behalf.':action==='deliver'?'The approved version is locked for the delivered project.':'Explain the required changes for the next artwork version.'}</div><label>Approval evidence / comments<textarea name="comment" required></textarea></label>${formActions('Confirm '+action)}</form>`);bindForm(async fd=>{await api('projects/'+id,'POST',{action,artwork_id:p.artworks[0]?.id,comment:fd.get('comment')});await projectsPage();projectDetail(id);toast('Project updated');});}
async function reportsPage(){const r=await api('profitability');const value=n=>n===null?'Not recorded':money(n);$('#content').innerHTML=pageHead('Purchases, sales & profit','Follow each product from supplier bill or production batch to its sale.',`<a class="secondary" href="/api/export?type=stock">Stock CSV</a><a class="primary" href="/api/export?type=profit">Profit CSV</a>`)+`<div class="notice">Gross profit = sales after discounts, excluding tax − cost of goods sold. It excludes general business expenses. Stock is consumed in receipt order. Existing stock is valued from configured costs when tracking begins; historical invoices without cost snapshots remain uncosted.</div><div class="stats">${reportStat('Purchases excluding tax',money(r.purchase_cents),'Supplier bills','')}${reportStat('Sales excluding tax',money(r.revenue_cents),'Active posted sales','')}${reportStat('Cost of goods sold',value(r.cogs_cents),'Stock cost captured on sale','')}${reportStat('Gross profit',value(r.gross_profit_cents),'Before general expenses','')}</div><p class="muted">Inventory value: <b>${money(r.stock_value_cents)}</b> · ${r.estimated_cost_documents} invoices include estimated costs · ${r.missing_cost_documents} invoices have missing historical costs.</p>`+panel('Product purchase and sales ledger',table(['Product / unit','Bought qty','Purchase cost','Sold qty','Sales ex. tax','Cost of goods sold','Gross profit','Remaining / value'],r.products.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.sku)} · ${esc(p.unit)}</small></td><td>${quantity(p.purchased_milli)}</td><td>${money(p.purchase_cents)}</td><td>${quantity(p.sold_milli)}</td><td>${money(p.revenue_cents)}</td><td>${p.missing_cost_lines?'Not fully recorded':money(p.cogs_cents)}</td><td>${p.missing_cost_lines?'Not fully recorded':money(p.gross_profit_cents)}</td><td>${quantity(p.stock_milli)}<small>${money(p.stock_value_cents)}</small></td></tr>`)))+panel('Profit by sales invoice',table(['Invoice','Sales ex. tax','Cost','Gross profit','Cost status'],r.invoices.map(i=>`<tr><td><button class="subtle" onclick="documentDetail(${i.id})">${esc(i.number)}</button></td><td>${money(i.revenue_cents)}</td><td>${value(i.cogs_cents)}</td><td>${value(i.gross_profit_cents)}</td><td>${i.cogs_cents===null?'Missing historical cost':i.estimated?'Includes estimates':'Recorded stock cost'}</td></tr>`)));}

async function settingsPage(){const s=state.boot.settings;let users=[];if(can())users=(await api('users')).users;const logs=(await api('audit')).audit;$('#content').innerHTML=pageHead('Company & access','Your branding, people, permissions and activity history.',`<button class="secondary" onclick="locationDialog()">+ Stock location</button><button class="primary" onclick="companyDialog()">Edit company</button>`)+panel('Your installation',`<div class="panel-body"><div class="detail-grid"><div><h2>${esc(s.company_name)}</h2><p class="muted">${esc(s.address)}<br>${esc(s.email)} · ${esc(s.phone)}</p><small>Currency ${esc(s.currency)} · Tax ID ${esc(s.tax_id||'not configured')}</small></div><div class="notice">Private single-company installation.<br>Development release 0.1.0.<br>Local LAN operation is supported by the server. Hybrid branch syncing, electronic invoicing, Arabic and terminal drivers are not enabled.</div></div></div>`)+ (can()?panel('Team access',table(['Name','Email','Role','Status'],users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${badge(u.active?'Active':'Disabled')} ${u.id!==state.boot.user.id?`<button class="subtle" onclick="toggleUser(${u.id},${!u.active})">${u.active?'Disable':'Enable'}</button>`:''}</td></tr>`)),'<button class="subtle" onclick="userDialog()">+ Invite / create user</button>'):'')+panel('Recent activity',table(['Time','User','Action','Record'],logs.map(l=>`<tr><td>${date(l.created_at)}</td><td>${esc(l.user||'System')}</td><td>${esc(l.action)}</td><td>${esc(l.subject)}</td></tr>`)));}
function companyDialog(){const s=state.boot.settings;modal('Company details',`<form><div class="form-grid">${field('Company name','company_name',s.company_name)}${field('Email','email',s.email,'email')}${field('Phone','phone',s.phone)}${field('Tax identifier','tax_id',s.tax_id)}${field('Currency · three-letter code','currency',s.currency)}<label class="span2">Address<textarea name="address">${esc(s.address)}</textarea></label></div>${formActions('Save company')}</form>`);bindForm(async fd=>{await api('settings','POST',Object.fromEntries(fd));state.boot=await api('bootstrap');companyHeader();closeModal();toast('Company updated');await settingsPage();});}
function userDialog(){modal('Create team access',`<form><div class="form-grid">${field('Full name','name')}${field('Email address','email','','email')}${field('Initial password · at least 12 characters','password','','password')}<label>Role<select name="role">${selectOptions(['manager','warehouse','production','cashier','designer','accountant','owner'])}</select></label></div><p class="form-hint">Share credentials securely. Users can change their password from their profile. Only owners create accounts.</p>${formActions('Create account')}</form>`);bindForm(async fd=>{await api('users','POST',Object.fromEntries(fd));closeModal();toast('User created');await settingsPage();});}
async function toggleUser(id,active){try{await api('users/'+id,'POST',{active});toast('User access updated');await settingsPage();}catch(e){toast(e.message);}}
function locationDialog(){modal('Add stock location',`<form>${field('Location name','name')}<label style="margin-top:15px">Type<select name="kind">${selectOptions(['warehouse','shop'])}</select></label>${formActions('Create location')}</form>`);bindForm(async fd=>{await api('locations','POST',Object.fromEntries(fd));location.reload();});}
function passwordDialog(){modal('Change your password',`<form>${field('Current password','current_password','','password')}${field('New password · at least 12 characters','password','','password')}${field('Confirm new password','password_confirmation','','password')}${formActions('Change password')}</form>`);bindForm(async fd=>{await api('password','POST',Object.fromEntries(fd));closeModal();toast('Password changed');});}
function companyHeader(){$('#company-name').textContent=state.boot.settings.company_name;$('#footer-company').textContent=state.boot.settings.company_name;$('#user-name').textContent=state.boot.user.name;$('#user-role').textContent=state.boot.user.role;$('#avatar').textContent=state.boot.user.name[0].toUpperCase();}
async function start(){setupNavigation();try{state.boot=await api('bootstrap');state.location=Number(localStorage.getItem('atelier-location')||state.boot.locations[0]?.id||1);if(!state.boot.locations.some(l=>l.id===state.location))state.location=state.boot.locations[0]?.id;companyHeader();$('#location-picker').innerHTML=state.boot.locations.map(l=>`<option value="${l.id}" ${l.id===state.location?'selected':''}>${esc(l.name)}</option>`).join('');$('#location-picker').addEventListener('change',async e=>{state.location=Number(e.target.value);localStorage.setItem('atelier-location',state.location);state.cart=[];await render();});window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const focus=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});await render();}catch(e){$('#content').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
start();

function cartSet(id,value){const p=state.products.find(p=>p.id===id);if(!/^\d+(\.\d{1,3})?$/.test(value)||Number(value)<=0||(['piece','bottle','box','carton'].includes(p.unit)&&!Number.isInteger(Number(value)))){toast('Enter a positive quantity; counted products need whole units.');cartRender();return;}const line=state.cart.find(l=>l.id===id);line.qty=Number(value);cartRender();}
function extraCostFields(prefix=''){return ['labour','overhead','freight','other'].map(k=>field((prefix?'Estimated ':'')+k[0].toUpperCase()+k.slice(1)+' cost · whole batch',prefix+k+'_cost','0.00')).join('');}
function costSheetView(c,title){if(!c)return '';return `<section class="cost-sheet"><div class="section-label">${esc(title)}</div><div class="metric-grid"><div><small>Total production cost</small><b>${money(c.total_cents)}</b></div><div><small>Cost per ${title.includes('Recorded')?'accepted':'planned'} unit</small><b>${c.unit_cost_cents===null?'No accepted output':money(c.unit_cost_cents)}</b></div><div><small>Output basis</small><b>${c.output} units</b></div></div>${table(['Cost component','Amount'],[['Ingredients',c.ingredients_cents],['Packaging',c.packaging_cents],...Object.entries(c.extras||{}).filter(([k,v])=>k!=='legacy_cents'||v).map(([k,v])=>[k.replace('_cents','').replace('legacy','Additional legacy cost'),v])].filter(([k,v])=>v!==undefined).map(([k,v])=>`<tr><td>${esc(k[0].toUpperCase()+k.slice(1))}</td><td>${money(v)}</td></tr>`))}${c.rows?.length?`<details><summary>Material quantities and unit costs</summary>${table(['Material','Quantity / unit','Unit cost','Total'],c.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${quantity(r.quantity_milli)} ${esc(r.unit)}</td><td>${money(r.unit_cost_cents)}</td><td>${money(r.cost_cents)}</td></tr>`))}</details>`:''}</section>`;}
function batchCostView(b){const c=b.costing;if(!c)return '';const a=c.actual,e=c.estimate;return `<div class="cost-review">${costSheetView(a||c.issued||e,a?'Recorded batch cost':c.issued?'Issued material cost':'Estimated batch cost')}${a&&e?`<p>Cost variance against estimate: <b>${money(a.total_cents-e.total_cents)}</b> · ${b.rejected} rejected units</p>`:''}${a&&a.unit_cost_cents!==null?`<div class="notice">At the current selling price of ${money(b.selling_price_cents)} per unit, estimated gross profit is <b>${money(b.selling_price_cents-a.unit_cost_cents)}</b> per unit (${b.selling_price_cents?((b.selling_price_cents-a.unit_cost_cents)/b.selling_price_cents*100).toFixed(1):'0'}% margin). Excludes sales taxes and selling expenses. This is a current-price estimate; invoice profit uses the actual sale price.</div>`:''}${(a||c.issued)&&e?`<details><summary>Original estimate</summary>${costSheetView(e,'Original estimated batch cost')}</details>`:''}<p class="form-hint">Issued material cost comes from the stock lots consumed. New purchases use supplier bill prices after discounts, excluding tax. Recipe quantities are used; measured consumption overrides remain pending.</p></div>`;}

function invoiceCostView(d){const p=d.profit;if(!p)return '';return `<section class="internal-costs"><div class="section-label">Internal cost & profit · excluded from customer print</div>${!p.active?'<p class="notice">This sale has been returned and is excluded from active sales profit.</p>':''}${table(['Product','Quantity / unit','Sale ex. tax','Stock cost','Gross profit','Source lots'],d.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${quantity(l.quantity_milli)} ${esc(l.unit)}</td><td>${money(l.subtotal_cents)}</td><td>${l.cogs_cents===null||l.cogs_cents===undefined?'Not recorded':money(l.cogs_cents)}</td><td>${l.cogs_cents===null||l.cogs_cents===undefined?'Not recorded':money(l.subtotal_cents-l.cogs_cents)}</td><td>${(l.cost_allocations||[]).map(a=>esc(a.lot||a.cost_basis)).join(', ')||'—'}</td></tr>`))}<div class="metric-grid"><div><small>Sales excluding tax</small><b>${money(p.revenue_cents)}</b></div><div><small>Cost of goods sold</small><b>${p.cogs_cents===null?'Not recorded':money(p.cogs_cents)}</b></div><div><small>Gross profit</small><b>${p.gross_profit_cents===null?'Not recorded':money(p.gross_profit_cents)}</b></div></div><p class="form-hint">${p.estimated?'Includes costs estimated from opening/configured values.':'Costs are captured from the stock lots consumed by this sale.'} General business expenses are excluded.</p></section>`;}

function profileFor(p){return typeof p.fragrance_profile==='string'?JSON.parse(p.fragrance_profile):p.fragrance_profile||{};}
function fragranceProfileFields(p){const f=profileFor(p);return `<div class="span2 section-label">Fragrance profile</div>${[['Top notes · opening','top_notes'],['Middle / heart notes','heart_notes'],['Base notes · dry-down','base_notes']].map(([label,k])=>field(label+' · comma separated',k,(f[k]||[]).join(', '))).join('')}<label class="span2">What does it smell like?<textarea name="smell_description" placeholder="Describe freshness, sweetness, warmth, texture and how the scent develops.">${esc(f.smell_description||'')}</textarea></label>${[['Scent intensity','intensity'],['Observed lasting time','longevity'],['Projection / scent trail','projection'],['Best season','season'],['Recommended occasion','occasion']].map(([label,k])=>field(label,k,f[k]||'')).join('')}<p class="form-hint span2">Enter your product's own notes and tested observations. Lasting time and projection can vary with skin, weather and application.</p>`;}
function fragranceProfileView(p){if(!['finished','raw','resale','intermediate'].includes(p.kind))return '';const f=profileFor(p);return `<section class="fragrance-profile"><div class="section-label">Fragrance profile</div><p class="smell-description">${esc(f.smell_description||'Smell description not recorded yet.')}</p><div class="notes-pyramid">${[['Top notes','First impression / opening','top_notes'],['Middle / heart notes','The heart of the fragrance','heart_notes'],['Base notes','The lasting dry-down','base_notes']].map(([label,help,k])=>`<div class="note-layer"><h3>${label}</h3><small>${help}</small><div class="scent-tags">${(f[k]||[]).length?f[k].map(n=>`<span>${esc(n)}</span>`).join(''):'<span>Not recorded</span>'}</div></div>`).join('')}</div><div class="profile-properties">${[['Intensity','intensity'],['Lasting time','longevity'],['Projection / trail','projection'],['Season','season'],['Occasion','occasion']].map(([label,k])=>`<div><small>${label}</small><b>${esc(f[k]||'Not recorded')}</b></div>`).join('')}</div></section>`;}

function reportStat(label,value,help){return `<div class="stat"><div class="stat-label">${esc(label)}</div><div class="stat-number">${esc(value)}</div><small>${esc(help)}</small></div>`;}

async function customersPage(){await loadLists();const customers=state.contacts.filter(c=>c.kind==='customer');$('#content').innerHTML=pageHead('Customer 360','Products, artwork, manufacturing and invoices in one record.',`<button class="primary" onclick="contactCreate('customer')">+ Add customer</button>`)+`<div class="customer-cards">${customers.map(c=>`<article class="customer-card"><div class="customer-monogram">${esc(c.name[0])}</div><h2>${esc(c.name)}</h2><p>${esc(c.phone||c.email||'Contact details not recorded')}</p><button class="primary" onclick="customer360(${c.id})">Open 360 view</button></article>`).join('')||'<div class="empty">Add your first customer.</div>'}</div>`;}
const stageLabels={vendor_started:'Vendor started',vendor_finished:'Vendor finished',packaging_ready:'Packaging ready',delivered:'Delivered',issue:'Mixing started',mature:'Maturation started',qc:'Quality check recorded',complete:'Production completed',recheck:'Quality recheck'};
function durationText(events,start,end){const a=events.find(e=>e.stage===start),b=[...events].reverse().find(e=>e.stage===end);return a&&b?Math.max(0,(new Date(b.at)-new Date(a.at))/3600000).toFixed(1)+' hours':'Not fully recorded';}
function progressTimeline(p){const b=p.batch,events=[{stage:'Brief saved',at:p.created_at,notes:p.brief},...(p.approvals||[]).map(a=>({stage:'Artwork '+a.decision,at:a.created_at,notes:(a.source==='customer'?'Customer '+a.customer_name+' · '+a.customer_phone+' · ':'')+(a.comment||'')})),...(b?.workflow_events||[]),...(p.workflow_events||[])].sort((a,b)=>new Date(a.at)-new Date(b.at));const ready=(p.workflow_events||[]).some(e=>e.stage==='packaging_ready'),delivered=(p.workflow_events||[]).some(e=>e.stage==='delivered');return `<div class="journey-strip">${[['Artwork',!!p.approved_artwork_id],['Production',b?.status==='Completed'],['Packaging',ready],['Delivery',delivered]].map(([label,done])=>`<span class="${done?'stage-done':'stage-pending'}">${done?'✓':'○'} ${label}</span>`).join('')}</div><div class="record-timeline">${events.map(e=>`<div class="record-event"><span></span><div><b>${esc(stageLabels[e.stage]||e.stage)}</b><small>${date(e.at)} · ${esc(e.notes||'')}</small></div></div>`).join('')}</div>${b?`<p class="muted">Batch ${esc(b.number)} · ${esc(b.status)} · Maturation due ${date(b.matures_at)}<br>Mixing duration: ${durationText(b.workflow_events||[],'issue','mature')} · Maturation to QC: ${durationText(b.workflow_events||[],'mature','qc')}</p>`:''}<p class="muted">Vendor duration: ${durationText(p.workflow_events||[],'vendor_started','vendor_finished')}</p>`;}
function artworkGallery(project){return `<div class="artwork-gallery">${(project.artworks||[]).map(a=>`<a class="artwork-tile" href="/api/artwork/${a.id}" target="_blank" rel="noopener">${a.mime?.startsWith('image/')?`<img src="/api/artwork/${a.id}" alt="${esc(a.filename)}">`:'<div class="artwork-file">PDF artwork</div>'}<b>${esc(a.filename)}</b><small>Version ${a.version} · ${date(a.created_at)}${project.approved_artwork_id===a.id?' · Approved':''}</small></a>`).join('')||'<p class="muted">Artwork not uploaded yet.</p>'}</div>`;}
function project360Panel(p){return `<section class="panel dossier-project"><div class="panel-head"><div><h2>${esc(p.name)}</h2><small>${esc(p.type)} · ${badge(p.status)}</small></div><div class="actions dossier-actions"><button class="secondary" onclick="customerArtworkLink(${p.id})">Artwork link / WhatsApp</button><button class="secondary" onclick="workflowDialog(${p.id})">Record stage</button></div></div><div class="panel-body"><p>${esc(p.brief)}</p><p>Packaging specifications: ${esc(p.specification||'Not recorded')}<br>Vendor: <b>${esc(p.supplier?.name||'Not linked')}</b></p>${progressTimeline(p)}${artworkGallery(p)}</div></section>`;}
async function customer360(id){if(location.hash!=='#customers'){location.hash='customers';return setTimeout(()=>customer360(id),250);}try{const d=await api('customers/'+id+'/360');state.customerDossier=d;state.currentCustomer=id;const posted=d.documents.filter(i=>['Sale','Invoice'].includes(i.kind)&&i.status==='Posted'),rev=posted.reduce((n,i)=>n+i.subtotal_cents,0),balance=posted.reduce((n,i)=>n+i.total_cents-i.paid_cents,0);const counts=['Artwork approved','Production complete','Packaging ready','Delivered'].map((name,index)=>({name,value:d.projects.filter(p=>index===0?p.approved_artwork_id:index===1?p.batch?.status==='Completed':(p.workflow_events||[]).some(e=>e.stage===(index===2?'packaging_ready':'delivered'))).length}));$('#content').innerHTML=pageHead(d.customer.name,'Customer 360 · internal company record',`<button class="secondary" onclick="customerProfileDialog(${id})">Edit profile / phone</button><button class="secondary" onclick="customersPage()">Customer list</button><button class="primary" onclick="printCustomer360()">Print 360 record</button>`)+`<div class="dossier-sheet"><p class="customer-contact">${esc(d.customer.phone||'')} ${esc(d.customer.email||'')}<br>${esc(d.customer.address||'')}</p><div class="stats">${reportStat('Linked products',d.products.length,'From projects and invoices')}${reportStat('Projects',d.projects.length,'Design and packaging')}${reportStat('Sales excluding tax',money(rev),'Active posted invoices')}${reportStat('Outstanding',money(balance),'Customer balance')}</div><section class="panel"><div class="panel-head"><h2>Products</h2></div><div class="panel-body"><div class="catalogue">${d.products.map(p=>`<article class="product-card" onclick="product360(${p.id})">${productArt(p)}<div class="product-info"><h3>${esc(p.name)}</h3><p>${esc(p.size||p.sku)}</p><button class="subtle">Open full product record</button></div></article>`).join('')||'<p>Link a product to a customer project or create an invoice to build this record.</p>'}</div></div></section><section class="panel"><div class="panel-head"><h2>Order progress</h2></div><div class="panel-body progress-chart">${counts.map(c=>`<div><span>${esc(c.name)}</span><div><i style="width:${d.projects.length?c.value/d.projects.length*100:0}%"></i></div><b>${c.value} / ${d.projects.length}</b></div>`).join('')}</div></section>${d.projects.map(project360Panel).join('')}${panel('Invoices and quotations',table(['Document','Type','Status','Total','Paid'],d.documents.map(i=>`<tr><td><button class="subtle dossier-actions" onclick="documentDetail(${i.id})">${esc(i.number)}</button><span class="print-only">${esc(i.number)}</span></td><td>${esc(i.kind)}</td><td>${esc(i.status)}</td><td>${money(i.total_cents)}</td><td>${money(i.paid_cents)}</td></tr>`)))}</div>`;}catch(e){toast(e.message);}}
async function printCustomer360(){try{toast('Preparing complete customer record…');const records=await Promise.all(state.customerDossier.products.map(p=>api('products/'+p.id+'/360')));modal(state.customerDossier.customer.name+' · 360 record',`<article class="document-preview"><h1>${esc(state.customerDossier.customer.name)}</h1><p>Confidential internal record · ${new Date().toLocaleDateString('en')}</p>${$('.dossier-sheet').innerHTML}</article>${records.map(productRecordMarkup).join('')}<div class="form-actions"><button class="primary" onclick="window.print()">Print / save complete PDF</button></div>`,true);}catch(e){toast(e.message);}}
async function product360(id){try{const d=await api('products/'+id+'/360');modal(d.product.name+' · complete product record',productRecordMarkup(d),true);}catch(e){toast(e.message);}}
function workflowDialog(id){modal('Record project progress',`<form><label>Completed stage<select name="stage">${Object.entries(stageLabels).filter(([k])=>['vendor_started','vendor_finished','packaging_ready','delivered'].includes(k)).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>When completed (optional)<input type="datetime-local" name="performed_at"></label><label>Notes / evidence<textarea name="notes" required placeholder="Record what was completed and any vendor reference."></textarea></label><p class="form-hint">The system records the time of this entry. Packaging needs approved artwork; delivery needs packaging ready and the linked batch completed.</p>${formActions('Save stage')}</form>`);bindForm(async(fd,key)=>{const v=Object.fromEntries(fd);if(v.performed_at)v.performed_at=new Date(v.performed_at).toISOString();else delete v.performed_at;await api('projects/'+id+'/workflow','POST',v,key);closeModal();toast('Stage recorded');if(state.currentCustomer)await customer360(state.currentCustomer);else await projectsPage();});}

async function projectLinksDialog(id){await loadLists();state.batches=(await api('batches')).batches;const p=state.projects.find(p=>p.id===id)||state.customerDossier?.projects.find(p=>p.id===id);modal('Link project records',`<form><div class="form-grid"><label>Customer<select name="contact_id">${options(state.contacts.filter(c=>c.kind==='customer'),'name',p?.contact_id,'Internal project')}</select></label><label>Product<select name="product_id">${options(state.products,'name',p?.product_id,'No product')}</select></label><label>Production batch<select name="batch_id">${options(state.batches.map(b=>({...b,name:b.number+' · '+b.product})),'name',p?.batch_id,'No batch')}</select></label><label>Packaging / printing supplier<select name="supplier_id">${options(state.contacts.filter(c=>c.kind==='supplier'),'name',p?.supplier_id,'No supplier')}</select></label></div>${formActions('Save links')}</form>`);bindForm(async fd=>{const v=Object.fromEntries(fd);for(const k in v)v[k]=v[k]?Number(v[k]):null;await api('projects/'+id+'/links','POST',v);closeModal();toast('Records linked');await projectsPage();});}

function productRecordMarkup(d){const p=d.product;return `<article class="document-preview product-dossier"><p class="eyebrow">Confidential internal product record</p><h1>${esc(p.name)}</h1><p>${esc(p.sku)} · ${esc(p.concentration||p.kind)} · ${esc(p.size||p.unit)} · ${esc(p.origin||'Origin not recorded')}</p><div class="dossier-product-images">${p.images?.length?p.images.map(i=>`<img src="${i.url}" alt="${esc(i.alt)}">`).join(''):''}</div>${fragranceProfileView(p)}${panel('Formula versions',d.formulas.map(f=>`<div class="panel-body"><h3>${esc(f.name)} · v${f.version} · ${esc(f.status)}</h3><p>Maturation plan: ${f.maturation_days} days</p>${table(['Ingredient / packaging','Quantity per bottle','Unit'],[...f.ingredients,...f.packaging].map(i=>`<tr><td>${esc(i.name)}</td><td>${quantity(i.quantity_milli)}</td><td>${esc(i.unit)}</td></tr>`))}<p>${esc(f.instructions||'')}</p></div>`).join('')||'<div class="empty">No formula linked to this product.</div>')}${panel('Production batches',d.batches.map(b=>`<div class="panel-body"><h3>${esc(b.number)} · ${esc(b.status)}</h3><p>Planned ${b.planned} · Accepted ${b.accepted} · Rejected ${b.rejected}<br>Maturation due: ${date(b.matures_at)}</p>${costSheetView(b.costing?.actual||b.costing?.issued||b.costing?.estimate,'Batch cost')}<p>Mixing: ${durationText(b.workflow_events||[],'issue','mature')} · Maturation to QC: ${durationText(b.workflow_events||[],'mature','qc')}</p><p>${esc(b.qc_notes||'')}</p></div>`).join('')||'<div class="empty">No production batches yet.</div>')}${d.projects.map(project360Panel).join('')}${panel('Supplier purchase history',table(['Supplier','Bill / reference','Date','Quantity','Price per unit','Total ex. tax'],d.purchases.map(i=>`<tr><td>${esc(i.supplier||'Not recorded')}</td><td>${esc(i.number)}<small>${esc(i.bill_reference||'')}</small></td><td>${date(i.created_at)}</td><td>${quantity(i.quantity_milli)} ${esc(p.unit)}</td><td>${money(i.price_cents)}</td><td>${money(i.subtotal_cents)}</td></tr>`)))}</article><div class="form-actions"><button class="primary" onclick="window.print()">Print / save product PDF</button></div>`;}

async function customerProfileDialog(id){
 const c=state.contacts.find(c=>c.id===id)||state.customerDossier?.customer;
 modal('Edit customer profile',`<form><div class="form-grid">${field('Name / company','name',c.name)}${field('Email','email',c.email,'email')}${field('Phone with country code','phone',c.phone,'tel')}<label class="span2">Address<textarea name="address">${esc(c.address)}</textarea></label></div><p class="form-hint">WhatsApp sharing uses this saved phone number. Updating it closes existing artwork links; create a fresh link afterwards.</p>${formActions('Save profile')}</form>`);
 bindForm(async fd=>{await api('contacts/'+id,'POST',Object.fromEntries(fd));await loadLists();closeModal();toast('Customer profile saved');await customer360(id);});
}
async function customerArtworkLink(id){
 try{const d=await api('projects/'+id+'/customer-link');const l=d.link;
 modal('Customer artwork link',`<p>Share artwork for this project. The customer can review your mockup, approve the latest version or request changes.</p>${l?`<div class="notice">${esc(l.customer)} · ${esc(l.phone)}<br>Expires ${date(l.expires_at)} · Customer uploads ${l.allow_upload?'enabled':'disabled'}</div><label>Artwork link<input id="customer-artwork-url" readonly value="${esc(l.url)}"></label><div class="actions" style="margin-top:18px"><button class="secondary" onclick="copyArtworkLink()">Copy link</button><a class="secondary" target="_blank" rel="noopener noreferrer" href="${esc(l.url)}">Preview customer page</a><a class="primary" target="_blank" rel="noopener noreferrer" href="${esc(l.whatsapp_url)}">Share on WhatsApp</a></div><p class="form-hint">Opens a prepared WhatsApp message to the saved customer number. Press Send in WhatsApp to send it.</p><button class="danger" style="margin-top:18px" onclick="manageArtworkLink(${id},'revoke')">Close this link</button>`:`<div class="notice">Link a customer and save their phone number with country code in Customer 360 first.</div><label class="checkbox"><input id="allow-customer-upload" type="checkbox" checked> Allow customer artwork uploads</label><div class="form-actions"><button class="primary" onclick="manageArtworkLink(${id},'create')">Create artwork link</button></div>`}<div id="link-error" class="error" hidden style="margin-top:15px"></div>`,true);
 }catch(e){toast(e.message);}
}
async function manageArtworkLink(id,action){
 if(state.busy)return;state.busy=true;
 try{await api('projects/'+id+'/customer-link','POST',{action,allow_upload:$('#allow-customer-upload')?.checked??true});await customerArtworkLink(id);toast(action==='create'?'Customer artwork link created':'Artwork link closed');}
 catch(e){$('#link-error').hidden=false;$('#link-error').textContent=e.message;}
 finally{state.busy=false;}
}
async function copyArtworkLink(){const input=$('#customer-artwork-url');try{await navigator.clipboard.writeText(input.value);toast('Artwork link copied');}catch{input.focus();input.select();toast('Select and copy the artwork link.');}}
